PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT (COUNT(?article) AS ?count)
WHERE {
?article wdt:P31/wdt:P279* wd:Q13442814
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT (COUNT(?item) AS ?count)
WHERE { ?item wdt:P625 [] }

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT (COUNT(DISTINCT ?obj) AS ?count) WHERE {
?obj wdt:P31/wdt:P279* wd:Q43229
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
SELECT ?work ?title ?year ?english ?french WHERE {
  ?work wdt:P50 wd:Q9068
OPTIONAL{?work wdt:P577 ?pubdate}
BIND(YEAR(?pubdate) as ?year)
OPTIONAL{ ?english schema:about ?work ; schema:isPartOf <https://en.wikipedia.org/> }
OPTIONAL{ ?french schema:about ?work ; schema:isPartOf <https://fr.wikipedia.org/> }
#OPTIONAL{ ?german schema:about ?work ; schema:isPartOf <https://de.wikipedia.org/> }
OPTIONAL{ ?work rdfs:label ?title filter(lang(?title) = "en") }
}

#defaultView:Map{"hide": ["?coord", "?layer"]}
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  wd:   <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT DISTINCT  ?person ?name ?birthplace ?birthyear ?coord ?layer
WHERE
  {   { ?person  wdt:P106  wd:Q188094 }
    UNION
      { ?person  wdt:P101  wd:Q8134 }
    MINUS
      { ?person  wdt:P106  wd:Q188094 ;
                 wdt:P101  wd:Q8134
      }
    ?person  wdt:P570  ?dod ;
             wdt:P19   ?place .
    ?place   wdt:P625  ?coord
    OPTIONAL
      { ?person  wdt:P569  ?dob }
    BIND(year(?dob) AS ?birthyear)
    BIND(if(( ?birthyear < 1700 ), "Pre-1700", if(( ?birthyear < 1751 ), "1700-1750", if(( ?birthyear < 1801 ), "1751-1800", if(( ?birthyear < 1851 ), "1801-1850", if(( ?birthyear < 1901 ), "1851-1900", if(( ?birthyear < 1951 ), "1901-1950", "Post-1950")))))) AS ?layer)
    OPTIONAL
      { ?person  rdfs:label  ?person__label_value
        FILTER ( lang(?person__label_value) = "en" )
      }
    OPTIONAL
      { ?person  rdfs:label  ?person__label_value
        FILTER ( lang(?person__label_value) = "mul" )
      }
    BIND(if(bound(?person__label_value), ?person__label_value, if(( isURI(?person) && strstarts(str(?person), "http://www.wikidata.org/entity/") ), strafter(str(?person), "entity/"), str(?person))) AS ?name)
    OPTIONAL
      { ?place  rdfs:label  ?place__label_value
        FILTER ( lang(?place__label_value) = "en" )
      }
    OPTIONAL
      { ?place  rdfs:label  ?place__label_value
        FILTER ( lang(?place__label_value) = "mul" )
      }
    BIND(if(bound(?place__label_value), ?place__label_value, if(( isURI(?place) && strstarts(str(?place), "http://www.wikidata.org/entity/") ), strafter(str(?place), "entity/"), str(?place))) AS ?birthplace)
  }
ORDER BY ?birthyear

#defaultView:Map{"hide": ["?coord"]}
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  wd:   <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?coord ?birthyear ?birthplace ?name ?person
WHERE
  {   { ?person  wdt:P106  wd:Q188094 }
    UNION
      { ?person  wdt:P101  wd:Q8134 }
    MINUS
      { ?person  wdt:P106  wd:Q188094 ;
                 wdt:P101  wd:Q8134
      }
    ?person  wdt:P19   ?place .
    ?place   wdt:P625  ?coord
    OPTIONAL
      { ?person  wdt:P569  ?dob }
    MINUS
      { ?person  wdt:P570  ?dod }
    BIND(year(?dob) AS ?birthyear)
    OPTIONAL
      { ?person  rdfs:label  ?person__label_value
        FILTER ( lang(?person__label_value) = "en" )
      }
    OPTIONAL
      { ?person  rdfs:label  ?person__label_value
        FILTER ( lang(?person__label_value) = "mul" )
      }
    BIND(if(bound(?person__label_value), ?person__label_value, if(( isURI(?person) && strstarts(str(?person), "http://www.wikidata.org/entity/") ), strafter(str(?person), "entity/"), str(?person))) AS ?name)
    OPTIONAL
      { ?place  rdfs:label  ?place__label_value
        FILTER ( lang(?place__label_value) = "en" )
      }
    OPTIONAL
      { ?place  rdfs:label  ?place__label_value
        FILTER ( lang(?place__label_value) = "mul" )
      }
    BIND(if(bound(?place__label_value), ?place__label_value, if(( isURI(?place) && strstarts(str(?place), "http://www.wikidata.org/entity/") ), strafter(str(?place), "entity/"), str(?place))) AS ?birthplace)
  }

PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  schema: <http://schema.org/>
PREFIX  wd:   <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT DISTINCT  ?person ?name ?birthyear ?deathyear ?enws ?quotes ?commonscat (URI(concat("https://www.gutenberg.org/ebooks/author/", ?gutenberg_id)) AS ?gutenberg) (URI(concat("https://doi.org/10.1093/ref:odnb/", ?odnb)) AS ?odnburl) (URI(concat("http://onlinebooks.library.upenn.edu/webbin/book/lookupname?key=", ?books)) AS ?booksurl) (URI(concat("https://www.britannica.com/", ?britannica)) AS ?britannicaurl) ?npg
WHERE
  {   { ?person  wdt:P106  wd:Q188094 }
    UNION
      { ?person  wdt:P101  wd:Q8134 }
    OPTIONAL
      { ?person  wdt:P1938  ?gutenberg_id }
    OPTIONAL
      { ?person  wdt:P4629  ?books }
    OPTIONAL
      { ?enws  schema:about     ?person ;
               schema:isPartOf  <https://en.wikisource.org/>
      }
    FILTER ( ( bound(?enws) || bound(?gutenberg_id) ) || bound(?books) )
    OPTIONAL
      { ?person  wdt:P570  ?death }
    BIND(year(?death) AS ?deathyear)
    OPTIONAL
      { ?person  wdt:P569  ?birth }
    BIND(year(?birth) AS ?birthyear)
    OPTIONAL
      { ?person  wdt:P1417  ?britannica }
    OPTIONAL
      { ?person  wdt:P1816  ?npg }
    OPTIONAL
      { ?person  wdt:P373  ?commonscat }
    OPTIONAL
      { ?quote  schema:about     ?person ;
                schema:isPartOf  <https://en.wikiquote.org/>
      }
    OPTIONAL
      { ?person  wdt:P1415  ?odnb }
    OPTIONAL
      { ?person  rdfs:label  ?person__label_value
        FILTER ( lang(?person__label_value) = "en" )
      }
    OPTIONAL
      { ?person  rdfs:label  ?person__label_value
        FILTER ( lang(?person__label_value) = "mul" )
      }
    BIND(if(bound(?person__label_value), ?person__label_value, if(( isURI(?person) && strstarts(str(?person), "http://www.wikidata.org/entity/") ), strafter(str(?person), "entity/"), str(?person))) AS ?name)
  }
ORDER BY ?deathyear

