grammar.full:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?thing ?name WHERE {
VALUES ?prop {wdt:P279 wdt:P31}
?thing ?prop wd:Q40998; 
  rdfs:label ?name FILTER (lang(?name)="en") FILTER STRENDS(?name, " phonology")
} ORDER BY ?name

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?person ?en_name WHERE {
{?person wdt:P2596 wd:Q11772. ?person wdt:P31 wd:Q5 } # Person & Culture: Ancient Greece
  UNION {?person wdt:P27/wdt:P31 wd:Q148837} # Citizen of a Polis
  UNION {?person wdt:P551/wdt:P31 wd:Q148837 } # Resident of a Polis
OPTIONAL{ ?person rdfs:label ?en_name FILTER(lang(?en_name) = "en")}
} ORDER BY ?en_name

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?person ?en_name ?name WHERE {
{?person wdt:P2596 wd:Q11772} # Culture: Ancient Greece
  UNION {?person wdt:P27/wdt:P31 wd:Q148837} # Citizen of a Polis
  UNION {?person wdt:P551/wdt:P31 wd:Q148837 } # Resident of a Polis
?person wdt:P1559 ?name;
OPTIONAL{ ?person rdfs:label ?en_name FILTER(lang(?en_name) = "en")}
} ORDER BY ?en_name

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?id (lang(?label) AS ?lang) ?label WHERE {
  ?item wdt:P2474 ?id;
rdfs:label ?label.
} ORDER BY ?id ?lang

PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  schema: <http://schema.org/>
PREFIX  wd:   <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?item ?itemLabel ?itemDescription ?birthdate ?deathdate
WHERE
  { ?item  wdt:P31   wd:Q5 ;
           wdt:P27   wd:Q183 ;
           wdt:P21   wd:Q6581072 ;
           wdt:P569  ?birthdate
    OPTIONAL
      { ?item  wdt:P570  ?deathdate }
    FILTER EXISTS { ?wen  schema:about       ?item ;
                          schema:inLanguage  "en"
                  }
    FILTER NOT EXISTS { ?wde  schema:about       ?item ;
                              schema:inLanguage  "de"
                      }
    OPTIONAL
      { ?item  rdfs:label  ?item__label_value
        FILTER ( lang(?item__label_value) = "en" )
      }
    OPTIONAL
      { ?item  rdfs:label  ?item__label_value
        FILTER ( lang(?item__label_value) = "de" )
      }
    OPTIONAL
      { ?item  rdfs:label  ?item__label_value
        FILTER ( lang(?item__label_value) = "mul" )
      }
    BIND(if(bound(?item__label_value), ?item__label_value, if(( isURI(?item) && strstarts(str(?item), "http://www.wikidata.org/entity/") ), strafter(str(?item), "entity/"), str(?item))) AS ?itemLabel)
    OPTIONAL
      { ?item  schema:description  ?item__description_value
        FILTER ( lang(?item__description_value) = "en" )
      }
    OPTIONAL
      { ?item  schema:description  ?item__description_value
        FILTER ( lang(?item__description_value) = "de" )
      }
    BIND(?item__description_value AS ?itemDescription)
  }
ORDER BY ?birthdate

PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  schema: <http://schema.org/>
PREFIX  wd:   <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?item ?itemLabel ?english ?afrik (SAMPLE(?workLabel) AS ?occupation)
WHERE
  { ?item  wdt:P27  wd:Q258 ;
           wdt:P21  wd:Q6581072
    MINUS
      { ?englishq  schema:about    ?item ;
                  schema:isPartOf  <https://en.wikiquote.org/>
      }
    MINUS
      { ?afrikq  schema:about     ?item ;
                 schema:isPartOf  <https://af.wikiquote.org/>
      }
    OPTIONAL
      { ?english  schema:about     ?item ;
                  schema:isPartOf  <https://en.wikipedia.org/>
      }
    OPTIONAL
      { ?afrik  schema:about     ?item ;
                schema:isPartOf  <https://af.wikipedia.org/>
      }
    OPTIONAL
      { ?item  wdt:P106  ?work }
    FILTER ( bound(?english) || bound(?afrik) )
    OPTIONAL
      { ?item  rdfs:label  ?item__label_value
        FILTER ( lang(?item__label_value) = "en" )
      }
    OPTIONAL
      { ?item  rdfs:label  ?item__label_value
        FILTER ( lang(?item__label_value) = "mul" )
      }
    BIND(if(bound(?item__label_value), ?item__label_value, if(( isURI(?item) && strstarts(str(?item), "http://www.wikidata.org/entity/") ), strafter(str(?item), "entity/"), str(?item))) AS ?itemLabel)
    BIND(if(bound(?work), ?work, "unbound") AS ?work__label_subject)
    OPTIONAL
      { ?work__label_subject
                  rdfs:label  ?work__label_value
        FILTER ( lang(?work__label_value) = "en" )
      }
    OPTIONAL
      { ?work__label_subject
                  rdfs:label  ?work__label_value
        FILTER ( lang(?work__label_value) = "mul" )
      }
    BIND(if(bound(?work__label_value), ?work__label_value, if(( isURI(?work) && strstarts(str(?work), "http://www.wikidata.org/entity/") ), strafter(str(?work), "entity/"), str(?work))) AS ?workLabel)
  }
GROUP BY ?item ?itemLabel ?english ?afrik

#defaultView:Map{"hide": ["?coord"]}
#title:Map of National Trust properties
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  wd:   <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?park ?parkLabel ?coord ?image ?web
WHERE
  { ?park  wdt:P127  wd:Q333515 ;
           wdt:P625  ?coord
    OPTIONAL
      { ?park  wdt:P18  ?image }
    OPTIONAL
      { ?park  wdt:P856  ?web }
    OPTIONAL
      { ?park  rdfs:label  ?park__label_value
        FILTER ( lang(?park__label_value) = "en" )
      }
    OPTIONAL
      { ?park  rdfs:label  ?park__label_value
        FILTER ( lang(?park__label_value) = "mul" )
      }
    BIND(if(bound(?park__label_value), ?park__label_value, if(( isURI(?park) && strstarts(str(?park), "http://www.wikidata.org/entity/") ), strafter(str(?park), "entity/"), str(?park))) AS ?parkLabel)
