PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
#defaultView:BubbleChart
SELECT ?status (COUNT(?item) AS ?count) WHERE {
  ?item p:P1435 ?s. ?s ps:P1435 wd:Q16024238.
  OPTIONAL{ ?item wdt:P6216 wd:Q50423863 . BIND("COPYyes" as ?copy)}
  OPTIONAL{ ?item wdt:P6216 wd:Q19652 . BIND("PDyes" as ?pd)}
  BIND(IF(BOUND(?copy), IF(BOUND(?pd), "Disputed", "Copyrighted"), IF(BOUND(?pd), "Public Domain", "Unclear") ) AS ?status)
} GROUP BY ?status
ORDER BY DESC(?count)

